[[nodiscard]] constexpr std::optional<CapabilityEntry> FindCapability(std::string_view spirv_name) noexcept
{
    const auto position = std::ranges::lower_bound(k_CapabilityEntries, spirv_name, {}, &CapabilityEntry::SpirvName);
    if (position == k_CapabilityEntries.end() || position->SpirvName != spirv_name)
    {
        return std::nullopt;
    }
    return *position;
}

