/** @brief The primary name of a SPIR-V capability: `name` itself, unless `name` is an alias. */
[[nodiscard]] constexpr std::string_view PrimaryCapabilityName(std::string_view name) noexcept
{
    const auto position = std::ranges::lower_bound(k_CapabilityAliases, name, {}, &CapabilityAlias::Alias);
    return position != k_CapabilityAliases.end() && position->Alias == name ? position->Name : name;
}

[[nodiscard]] constexpr std::span<const CapabilityEnable> EnablesOf(const CapabilityEntry& entry) noexcept
{
    return std::span<const CapabilityEnable>{ k_CapabilityEnables }.subspan(entry.FirstEnable, entry.EnableCount);
}

